   }
   "summary"->{
    val bestPrevious=recent.take(100).sumOf{it.value};val insight=when{summarySets==0->"No completed sets were recorded.";summaryVolume>bestPrevious/10.0&&summarySets>=8->"Strong training output. Volume was high relative to your recent logged baseline.";summarySets>=12->"Solid training density. Recovery, sleep and nutrition can now be compared against this session.";else->"Session captured. More repeated workouts will sharpen progression and recovery insights."}
    Column(Modifier.fillMaxWidth().background(ExerciseSoft,RoundedCornerShape(26.dp)).padding(20.dp)){Text("WORKOUT COMPLETE",color=ExerciseBlue,fontSize=9.sp,fontWeight=FontWeight.Black);Text("Nice work",color=ExerciseNavy,fontSize=27.sp,fontWeight=FontWeight.Black);Spacer(Modifier.height(10.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){ExerciseStat("SETS",summarySets.toString(),Modifier.weight(1f));ExerciseStat("VOLUME","${summaryVolume.roundToInt()} kg",Modifier.weight(1f));ExerciseStat("TIME","${summaryDuration}m",Modifier.weight(1f))};Spacer(Modifier.height(15.dp));Text("SUPERHUMAN INSIGHT",color=ExerciseGreen,fontSize=9.sp,fontWeight=FontWeight.Black);Text(insight,color=ExerciseInk,fontSize=11.sp,lineHeight=16.sp);Spacer(Modifier.height(14.dp));Text("This is a training-context observation, not a medical conclusion.",color=ExerciseMuted,fontSize=8.sp);Spacer(Modifier.height(14.dp));Box(Modifier.fillMaxWidth().background(ExerciseNavy,RoundedCornerShape(15.dp)).clickable{session.clear();workoutExercises.clear();startedAt=0L;mode="home"}.padding(13.dp),contentAlignment=Alignment.Center){Text("DONE",color=Color.White,fontSize=10.sp,fontWeight=FontWeight.Black)}}
   }
  }
  Text("Exercise data & illustrations by RepDB · repdb.co",color=ExerciseMuted,fontSize=8.sp,modifier=Modifier.padding(6.dp));Spacer(Modifier.height(18.dp))
 }
}

@Composable private fun QuickAction(title:String,subtitle:String,modifier:Modifier,onClick:()->Unit){Column(modifier.background(Color.White,RoundedCornerShape(17.dp)).clickable{onClick()}.padding(11.dp)){Text(title,color=ExerciseNavy,fontSize=9.sp,fontWeight=FontWeight.Black);Text(subtitle,color=ExerciseMuted,fontSize=7.sp)}}
@Composable private fun ExerciseStat(label:String,value:String,modifier:Modifier){Column(modifier.background(Color.White,RoundedCornerShape(16.dp)).padding(11.dp)){Text(label,color=ExerciseMuted,fontSize=8.sp,fontWeight=FontWeight.Bold);Spacer(Modifier.height(4.dp));Text(value,color=ExerciseNavy,fontSize=13.sp,fontWeight=FontWeight.Black)}}
@Composable private fun MiniVolumeChart(values:List<Float>){val maxV=(values.maxOrNull()?:1f).coerceAtLeast(1f);Canvas(Modifier.fillMaxWidth().height(46.dp).padding(top=6.dp)){if(values.size<2)return@Canvas;val step=size.width/(values.size-1);values.zipWithNext().forEachIndexed{i,(a,b)->drawLine(ExerciseBlue,Offset(step*i,size.height-(a/maxV)*size.height),Offset(step*(i+1),size.height-(b/maxV)*size.height),strokeWidth=4f)}}}
